'Custom_SMS_Guide_Title' => 'কীভাবে কনফিগার করবেন',
'Custom_SMS_Guide_Intro' => 'HTTP API আছে এমন যেকোনো SMS প্রোভাইডার যুক্ত করা যায়। আপনার প্রোভাইডারের API ডকুমেন্টেশন খুলে এন্ডপয়েন্ট, মেথড ও ঘরের নাম কপি করুন, তারপর প্লেসহোল্ডার ব্যবহার করে নিচে ম্যাপ করুন।',
'Custom_SMS_Guide_Placeholder_Phone' => 'প্রাপকের ফোন নম্বর',
'Custom_SMS_Guide_Placeholder_Message' => 'SMS-এর লেখা',
'Custom_SMS_Guide_Placeholder_Sender' => 'উপরে লেখা প্রেরক আইডি',
'Custom_SMS_Guide_Api_Url' => 'আপনার প্রোভাইডারের ডকুমেন্টেশন থেকে পূর্ণ এন্ডপয়েন্ট URL, যেমন https://api.provider.com/sms/send। URL-এ সরাসরি প্লেসহোল্ডারও ব্যবহার করা যায়, যেমন ...?to={phone}&text={message}।',
'Custom_SMS_Guide_Method' => 'POST সবচেয়ে প্রচলিত। GET শুধু তখনই বেছে নিন যখন আপনার প্রোভাইডার সবকিছু URL-এ আশা করে — তখন পেলোডের ঘরগুলো কোয়েরি প্যারামিটার হিসেবে যায়।',
'Custom_SMS_Guide_Content_Type' => '"json" পেলোডকে JSON বডি হিসেবে পাঠায় (application/json)। "form" এটিকে সাধারণ HTML ফরম হিসেবে পাঠায় (application/x-www-form-urlencoded)। আপনার প্রোভাইডার কোনটি আশা করে যাচাই করুন; GET-এর ক্ষেত্রে এটি উপেক্ষিত হয়।',
'Custom_SMS_Guide_Sender' => 'আপনার অনুমোদিত প্রেরক আইডি বা প্রেরক ফোন নম্বর। এটি শুধু {sender} প্লেসহোল্ডারটি পূরণ করে — পাঠানোর জন্য এটি পেলোড, হেডার বা URL-এ ব্যবহার করতে হবে।',
'Custom_SMS_Guide_Success_Keyword' => 'ঐচ্ছিক, তবে পরামর্শযোগ্য। কিছু প্রোভাইডার পাঠানো ব্যর্থ হলেও "200 OK" উত্তর দেয়। এমন একটি শব্দ বা অংশ লিখুন যা কেবল সফল উত্তরেই থাকে (যেমন success)। উত্তরে সেটি না থাকলে SMS ব্যর্থ ধরা হবে।',
'Custom_SMS_Guide_Headers' => 'আপনার প্রোভাইডারের প্রয়োজনীয় প্রমাণীকরণ হেডার, যেমন Authorization = Bearer YOUR_API_KEY অথবা Api-Key = YOUR_API_KEY। Content-Type যোগ করবেন না — এটি স্বয়ংক্রিয়ভাবে নির্ধারিত হয়।',
'Custom_SMS_Guide_Payload' => 'রিকোয়েস্ট বডির ঘরগুলো, আপনার প্রোভাইডারের ডকুমেন্টেশনে যেভাবে আছে হুবহু সেই নামে। মান হিসেবে প্লেসহোল্ডার ব্যবহার করুন, যেমন to = {phone}, message = {message}, from = {sender}।',
'Custom_SMS_Guide_Example' => 'পূর্ণ উদাহরণ',
'Custom_SMS_Guide_Default_Note' => 'সংরক্ষণের পর এই পৃষ্ঠার উপরে ডিফল্ট SMS গেটওয়ে হিসেবে "custom" নির্বাচন করে জমা দিন — নাহলে SMS আগের নির্বাচিত গেটওয়েই ব্যবহার করতে থাকবে।',
