'OfflinePayments' => 'অফলাইন পেমেন্ট',
'OfflinePaymentsIntro' => 'সিস্টেমের বাইরে পরিশোধ করা সবকিছু এখানে থাকে: ক্যাশ অন ডেলিভারি, মোবাইল ব্যাংকিং, GCash, ব্যাংক ট্রান্সফার এবং সংগ্রহের সময় নগদ। আপনি পরিশোধিত হিসেবে চিহ্নিত না করা পর্যন্ত এই অর্ডারগুলো পেমেন্ট-অপেক্ষমাণ থাকে। GCash ও ব্যাংক ট্রান্সফারে ক্রেতার কাছ থেকে স্ক্রিনশট, রেফারেন্স নম্বর ও পরিমাণ চাওয়া হয়, যা আপনি অর্ডারে অনুমোদন করেন।',
