'Ord_Guide_Intro' => 'আপনার অনলাইন স্টোরে দেওয়া একটি অর্ডার কীভাবে আপনার স্টক ও হিসাবে যায় এবং টাকাটা আসলে কোথায় রেকর্ড হয়।',
'Ord_Guide_Lifecycle_Title' => 'অর্ডারের অবস্থা',
'Ord_Guide_MarkPaid_Note' => 'এখানে দেখানো পেমেন্টের অবস্থা চেকআউটে করা পছন্দটিই রেকর্ড করে রাখে এবং অপরিবর্তিত থাকে। বিক্রয়টিই হিসাবের রেকর্ড, এবং সেটিই আপনার পেমেন্ট ও মুনাফা রিপোর্টে যায়। আপনি যা লিখেছেন তা দেখতে বা সম্পাদনা করতে বিক্রয়ে "পেমেন্ট দেখুন" ব্যবহার করুন।',
