'Ord_Guide_PaymentStatus_Tip' => 'চেকআউটে নির্ধারিত হয় এবং এখানে সম্পাদনা করা যায় না। পেমেন্ট কীভাবে রেকর্ড করবেন তা দেখতে ক্লিক করুন।',
'Ord_Guide_Payment_Failed' => 'গেটওয়ে পেমেন্টটি প্রত্যাখ্যান করেছে অথবা ক্রেতা এটি ছেড়ে দিয়েছেন। অর্ডারটি স্বয়ংক্রিয়ভাবে বাতিল হয়।',
'Ord_Guide_Payment_Intro' => 'এই কলামটি ক্রেতা চেকআউটে কীভাবে পরিশোধ করতে চেয়েছেন তা রেকর্ড করে। এটি স্টোরফ্রন্ট নির্ধারণ করে এবং এই পৃষ্ঠা থেকে সম্পাদনা করা যায় না — টাকাটা অর্ডার নিশ্চিত করার সময় তৈরি হওয়া বিক্রয়ে ট্র্যাক করা হয়।',
'Ord_Guide_Payment_Paid' => 'ক্রেতা ইতিমধ্যেই একটি পেমেন্ট গেটওয়ের মাধ্যমে অনলাইনে পরিশোধ করেছেন। অর্ডার নিশ্চিত করলে বিক্রয়টি পরিশোধিত হিসেবে তৈরি হয় এবং পেমেন্টটিও রেকর্ড হয়ে যায় — আর কিছু করার নেই।',
