'Ord_Guide_Lifecycle_Cancelled' => 'নিশ্চিত করার আগেই অর্ডারটি বাদ দেওয়া হয়েছে, তাই কোনো বিক্রয় তৈরি হয়নি এবং কোনো স্টকও কমেনি।',
'Ord_Guide_Lifecycle_Confirmed' => 'আপনি অর্ডারটি গ্রহণ করেছেন। Stocky আপনার নির্বাচিত গুদামে একটি বিক্রয় তৈরি করে ও স্টক কমায় — সেই বিক্রয়টিই আপনার স্টক, পেমেন্ট ও মুনাফা রিপোর্টের উৎস।',
'Ord_Guide_Lifecycle_Delivered' => 'ক্রেতা অর্ডারটি পেয়েছেন। এখান থেকেই ফেরতের সময়সীমা শুরু হয়।',
'Ord_Guide_Lifecycle_Pending' => 'একটি নতুন অর্ডার আপনার পর্যালোচনার অপেক্ষায়। শুধু অপেক্ষমাণ অর্ডারই নিশ্চিত বা বাতিল করা যায়।',
'Ord_Guide_Lifecycle_Shipped' => 'আপনি অর্ডারটি পাঠিয়েছেন। এটি শুধু সরবরাহের ধাপ: নিশ্চিত করার সময়ই স্টক কমে গেছে।',
'Ord_Guide_MarkPaid_Step1' => 'প্রথমে এখানে অর্ডারটি নিশ্চিত করুন — নিশ্চিত করলেই বিক্রয়টি তৈরি হয়।',
'Ord_Guide_MarkPaid_Step2' => 'বিক্রয় > সব বিক্রয় খুলে সেই বিক্রয়টি খুঁজুন (একই ক্রেতা, এবং বিস্তারিত পৃষ্ঠায় এটি কোন অনলাইন অর্ডার থেকে এসেছে তা দেখানো থাকে)।',
'Ord_Guide_MarkPaid_Step3' => 'সারির কার্যক্রম মেনু খুলে "পেমেন্ট তৈরি করুন" নির্বাচন করুন।',
'Ord_Guide_MarkPaid_Step4' => 'পরিমাণ, পেমেন্ট পদ্ধতি ও তারিখ লিখে সংরক্ষণ করুন। পরিমাণ অনুযায়ী বিক্রয়টি নিজে থেকেই আংশিক বা পরিশোধিত অবস্থায় চলে যায়।',
'Ord_Guide_Note_Cancel' => 'অর্ডার অপেক্ষমাণ থাকা অবস্থাতেই কেবল বাতিল করা যায়। একবার নিশ্চিত হয়ে গেলে তার বদলে বিক্রয় বা ক্রেতা ফেরতের মাধ্যমে সেটি ফিরিয়ে আনুন।',
'Ord_Guide_Note_Flagged' => '"চিহ্নিত" ট্যাগের মানে হলো চেকআউটে অর্ডারটি একটি জালিয়াতি যাচাইয়ে আটকেছে। কারণ দেখতে ট্যাগের ওপর মাউস রাখুন এবং নিশ্চিত করার আগে অর্ডারটি পর্যালোচনা করুন।',
'Ord_Guide_Note_Preorder' => 'প্রি-অর্ডার পণ্য স্টক যাচাই এড়িয়ে যায়, তাই সেগুলো থাকা অর্ডার স্টকে পরিমাণ না থাকলেও নিশ্চিত করা যায়।',
